  1→package jlsm.sstable;
  2→
  3→import jlsm.bloom.blocked.BlockedBloomFilter;
  4→import jlsm.core.bloom.BloomFilter;
  5→import jlsm.core.compression.CompressionCodec;
  6→import jlsm.core.model.Entry;
  7→import jlsm.core.model.Level;
  8→import jlsm.core.model.SequenceNumber;
  9→import jlsm.core.sstable.SSTableMetadata;
 10→import jlsm.core.sstable.SSTableWriter;
 11→import jlsm.sstable.internal.CompressionMap;
 12→import jlsm.sstable.internal.DataBlock;
 13→import jlsm.sstable.internal.EntryCodec;
 14→import jlsm.sstable.internal.SSTableFormat;
 15→
 16→import java.io.IOException;
 17→import java.lang.foreign.MemorySegment;
 18→import java.lang.foreign.ValueLayout;
 19→import java.nio.ByteBuffer;
 20→import java.nio.channels.FileChannel;
 21→import java.nio.channels.SeekableByteChannel;
 22→import java.nio.file.Files;
 23→import java.nio.file.Path;
 24→import java.nio.file.StandardOpenOption;
 25→import java.util.ArrayList;
 26→import java.util.List;
 27→import java.util.Objects;
 28→
 29→/**
 30→ * Writes entries to a new SSTable file using a trie-based key index.
 31→ *
 32→ * <p>
 33→ * Supports two file formats:
 34→ * <ul>
 35→ * <li><b>v1</b> — no compression (constructors without {@link CompressionCodec})</li>
 36→ * <li><b>v2</b> — per-block compression with a compression offset map (constructor with
 37→ * {@link CompressionCodec})</li>
 38→ * </ul>
 39→ *
 40→ * <p>
 41→ * State machine: {@code OPEN → FINISHED → CLOSED} and {@code OPEN → CLOSED}. Calling
 42→ * {@link #close()} without {@link #finish()} deletes the partial file.
 43→ */
 44→public final class TrieSSTableWriter implements SSTableWriter {
 45→
 46→    private enum State {
 47→        OPEN, FINISHED, CLOSED
 48→    }
 49→
 50→    private final long id;
 51→    private final Level level;
 52→    private final Path outputPath;
 53→    private final SeekableByteChannel channel;
 54→
 55→    // Data block accumulation
 56→    private DataBlock currentBlock = new DataBlock();
 57→    private long writePosition = 0L;
 58→
 59→    // v1: parallel lists of keys (raw byte[]) + absolute file offsets
 60→    // v2: parallel lists of keys + packed (blockIndex << 32 | intraBlockOffset)
 61→    private final List<byte[]> indexKeys = new ArrayList<>();
 62→    private final List<Long> indexOffsets = new ArrayList<>();
 63→
 64→    // Bloom filter
 65→    private BloomFilter bloomFilter;
 66→    private final BloomFilter.Factory bloomFactory;
 67→
 68→    // Compression (v2 only — null for v1)
 69→    private final CompressionCodec codec;
 70→    private final List<CompressionMap.Entry> compressionMapEntries = new ArrayList<>();
 71→    private int blockCount = 0;
 72→
 73→    // Stats
 74→    private long entryCount = 0L;
 75→    private long approximateSizeBytes = 0L;
 76→    private MemorySegment smallestKey = null;
 77→    private MemorySegment largestKey = null;
 78→    private SequenceNumber minSequence = null;
 79→    private SequenceNumber maxSequence = null;
 80→
 81→    // Previous key for ordering check
 82→    private byte[] lastKeyBytes = null;
 83→
 84→    private State state = State.OPEN;
 85→
 86→    /**
 87→     * Creates a v1 writer (no compression) with a {@link BlockedBloomFilter} at 1% FPR.
 88→     *
 89→     * @param id unique SSTable identifier
 90→     * @param level LSM level for this SSTable
 91→     * @param outputPath path to the output file; must not exist
 92→     * @throws IOException if the file cannot be opened
 93→     */
 94→    public TrieSSTableWriter(long id, Level level, Path outputPath) throws IOException {
 95→        this(id, level, outputPath, n -> new BlockedBloomFilter(n, 0.01), null);
 96→    }
 97→
 98→    /**
 99→     * Creates a v1 writer (no compression) with a custom bloom filter factory.
100→     *
101→     * @param id unique SSTable identifier
102→     * @param level LSM level for this SSTable
103→     * @param outputPath path to the output file; must not exist
104→     * @param bloomFactory factory used to create the bloom filter; must not be null
105→     * @throws IOException if the file cannot be opened
106→     */
107→    public TrieSSTableWriter(long id, Level level, Path outputPath,
108→            BloomFilter.Factory bloomFactory) throws IOException {
109→        this(id, level, outputPath, bloomFactory, null);
110→    }
111→
112→    /**
113→     * Creates a v2 writer with per-block compression using the given codec.
114→     *
115→     * <p>
116→     * Pass {@code null} for the codec to produce a v1 (uncompressed) file.
117→     *
118→     * @param id unique SSTable identifier
119→     * @param level LSM level for this SSTable
120→     * @param outputPath path to the output file; must not exist
121→     * @param bloomFactory factory used to create the bloom filter; must not be null
122→     * @param codec compression codec, or null for v1 format
123→     * @throws IOException if the file cannot be opened
124→     */
125→    public TrieSSTableWriter(long id, Level level, Path outputPath,
126→            BloomFilter.Factory bloomFactory, CompressionCodec codec) throws IOException {
127→        Objects.requireNonNull(level, "level must not be null");
128→        Objects.requireNonNull(outputPath, "outputPath must not be null");
129→        Objects.requireNonNull(bloomFactory, "bloomFactory must not be null");
130→        this.id = id;
131→        this.level = level;
132→        this.outputPath = outputPath;
133→        this.bloomFactory = bloomFactory;
134→        this.codec = codec;
135→        this.channel = Files.newByteChannel(outputPath, StandardOpenOption.CREATE_NEW,
136→                StandardOpenOption.WRITE);
137→    }
138→
139→    @Override
140→    public void append(Entry entry) throws IOException {
141→        Objects.requireNonNull(entry, "entry must not be null");
142→        if (state != State.OPEN) {
143→            throw new IllegalStateException("writer is not open (state=" + state + ")");
144→        }
145→
146→        byte[] keyBytes = entry.key().toArray(ValueLayout.JAVA_BYTE);
147→
148→        // Enforce strictly ascending key order
149→        if (lastKeyBytes != null) {
150→            int cmp = compareUnsigned(keyBytes, lastKeyBytes);
151→            if (cmp <= 0) {
152→                throw new IllegalArgumentException(
153→                        "keys must be strictly ascending; got key not greater than previous key");
154→            }
155→        }
156→
157→        // Encode using the already-extracted key bytes to avoid a redundant toArray
158→        byte[] encoded = EntryCodec.encode(entry, keyBytes);
159→
160→        if (codec != null) {
161→            // v2: store (blockIndex, intraBlockOffset) packed into a long
162→            int intraBlockOffset = currentBlock.byteSize();
163→            long packed = ((long) blockCount << 32) | (intraBlockOffset & 0xFFFFFFFFL);
164→            indexKeys.add(keyBytes);
165→            indexOffsets.add(packed);
166→        } else {
167→            // v1: store absolute file offset
168→            long entryAbsOffset = writePosition + currentBlock.byteSize();
169→            indexKeys.add(keyBytes);
170→            indexOffsets.add(entryAbsOffset);
171→        }
172→
173→        currentBlock.add(encoded);
174→        approximateSizeBytes += encoded.length;
175→
176→        // Update stats — reuse keyBytes; clone only for smallest (first entry)
177→        SequenceNumber seq = entry.sequenceNumber();
178→        if (smallestKey == null)
179→            smallestKey = MemorySegment.ofArray(keyBytes.clone());
180→        largestKey = MemorySegment.ofArray(keyBytes);
181→
182→        if (minSequence == null || seq.compareTo(minSequence) < 0)
183→            minSequence = seq;
184→        if (maxSequence == null || seq.compareTo(maxSequence) > 0)
185→            maxSequence = seq;
186→
187→        lastKeyBytes = keyBytes;
188→        entryCount++;
189→
190→        // Flush block if it exceeds the target size
191→        if (currentBlock.byteSize() >= SSTableFormat.DEFAULT_BLOCK_SIZE) {
192→            flushCurrentBlock();
193→        }
194→    }
195→
196→    private void flushCurrentBlock() throws IOException {
197→        if (currentBlock.count() == 0)
198→            return;
199→        byte[] blockBytes = currentBlock.serialize();
200→
201→        if (codec != null) {
202→            // v2: compress the block
203→            byte[] compressed = codec.compress(blockBytes, 0, blockBytes.length);
204→            byte actualCodecId;
205→            byte[] dataToWrite;
206→            if (compressed.length >= blockBytes.length) {
207→                // Incompressible — store raw with NONE codec ID
208→                dataToWrite = blockBytes;
209→                actualCodecId = CompressionCodec.none().codecId();
210→            } else {
211→                dataToWrite = compressed;
212→                actualCodecId = codec.codecId();
213→            }
214→            compressionMapEntries.add(new CompressionMap.Entry(writePosition, dataToWrite.length,
215→                    blockBytes.length, actualCodecId));
216→            writeBytes(dataToWrite);
217→        } else {
218→            // v1: write raw block
219→            writeBytes(blockBytes);
220→        }
221→        blockCount++;
222→        currentBlock = new DataBlock();
223→    }
224→
225→    private void writeBytes(byte[] bytes) throws IOException {
226→        ByteBuffer buf = ByteBuffer.wrap(bytes);
227→        while (buf.hasRemaining()) {
228→            channel.write(buf);
229→        }
230→        writePosition += bytes.length;
231→    }
232→
233→    @Override
234→    public SSTableMetadata finish() throws IOException {
235→        if (state != State.OPEN) {
236→            throw new IllegalStateException("finish() already called or writer is closed");
237→        }
238→        if (entryCount == 0) {
239→            throw new IllegalStateException("cannot finish an empty SSTable");
240→        }
241→
242→        // Flush remaining block
243→        flushCurrentBlock();
244→
245→        // Build bloom filter
246→        bloomFilter = bloomFactory.create((int) Math.max(1, entryCount));
247→        for (byte[] key : indexKeys) {
248→            bloomFilter.add(MemorySegment.ofArray(key));
249→        }
250→
251→        if (codec != null) {
252→            // v2 layout: [data blocks][compression map][key index][bloom filter][footer 64]
253→            long mapOffset = writePosition;
254→            CompressionMap compressionMap = new CompressionMap(compressionMapEntries);
255→            writeBytes(compressionMap.serialize());
256→            long mapLength = writePosition - mapOffset;
257→
258→            long indexOffset = writePosition;
259→            writeKeyIndexV2();
260→            long indexLength = writePosition - indexOffset;
261→
262→            long filterOffset = writePosition;
263→            MemorySegment filterBytes = bloomFilter.serialize();
264→            byte[] filterArray = filterBytes.toArray(ValueLayout.JAVA_BYTE);
265→            writeBytes(filterArray);
266→            long filterLength = writePosition - filterOffset;
267→
268→            writeFooterV2(mapOffset, mapLength, indexOffset, indexLength, filterOffset,
269→                    filterLength);
270→        } else {
271→            // v1 layout: [data blocks][key index][bloom filter][footer 48]
272→            long indexOffset = writePosition;
273→            writeKeyIndexV1();
274→            long indexLength = writePosition - indexOffset;
275→
276→            long filterOffset = writePosition;
277→            MemorySegment filterBytes = bloomFilter.serialize();
278→            byte[] filterArray = filterBytes.toArray(ValueLayout.JAVA_BYTE);
279→            writeBytes(filterArray);
280→            long filterLength = writePosition - filterOffset;
281→
282→            writeFooterV1(indexOffset, indexLength, filterOffset, filterLength);
283→        }
284→
285→        // fsync if supported (e.g., local FileChannel; skipped for object-storage channels)
286→        if (channel instanceof FileChannel fc)
287→            fc.force(true);
288→
289→        long sizeBytes = writePosition;
290→
291→        state = State.FINISHED;
292→
293→        return new SSTableMetadata(id, outputPath, level, smallestKey, largestKey, minSequence,
