255→    // ---- SSTableReader interface ----
256→
257→    @Override
258→    public SSTableMetadata metadata() {
259→        return metadata;
260→    }
261→
262→    @Override
263→    public Optional<Entry> get(MemorySegment key) throws IOException {
264→        Objects.requireNonNull(key, "key must not be null");
265→        checkNotClosed();
266→
267→        if (!bloomFilter.mightContain(key)) {
268→            return Optional.empty();
269→        }
270→
271→        Optional<Long> offsetOpt = keyIndex.lookup(key);
272→        if (offsetOpt.isEmpty()) {
273→            return Optional.empty();
274→        }
275→
276→        long offset = offsetOpt.get();
277→
278→        if (compressionMap != null) {
279→            // v2: offset is packed (blockIndex << 32 | intraBlockOffset)
280→            int blockIndex = (int) (offset >>> 32);
281→            int intraBlockOffset = (int) offset;
282→            byte[] decompressedBlock = readAndDecompressBlock(blockIndex);
283→            return Optional.of(EntryCodec.decode(decompressedBlock, intraBlockOffset));
284→        } else {
285→            // v1: offset is absolute file position
286→            byte[] entryBytes = readDataAtV1(offset, SSTableFormat.DEFAULT_BLOCK_SIZE);
287→            return Optional.of(EntryCodec.decode(entryBytes, 0));
288→        }
289→    }
290→
291→    @Override
292→    public Iterator<Entry> scan() throws IOException {
293→        checkNotClosed();
294→        if (compressionMap != null) {
295→            // v2: decompress all blocks and iterate
296→            byte[] allData = decompressAllBlocks();
297→            return new DataRegionIterator(allData, allData.length);
298→        } else {
299→            // v1: iterate raw data region
300→            byte[] data = getAllDataV1();
301→            return new DataRegionIterator(data, dataEnd);
302→        }
303→    }
304→
305→    @Override
306→    public Iterator<Entry> scan(MemorySegment fromKey, MemorySegment toKey) throws IOException {
307→        Objects.requireNonNull(fromKey, "fromKey must not be null");
308→        Objects.requireNonNull(toKey, "toKey must not be null");
309→        checkNotClosed();
310→        return new IndexRangeIterator(keyIndex.rangeIterator(fromKey, toKey));
311→    }
312→
313→    @Override
314→    public void close() throws IOException {
315→        if (closed)
316→            return;
317→        closed = true;
318→        if (lazyChannel != null) {
319→            lazyChannel.close();
320→        }
321→    }
322→
323→    // ---- v2 compression helpers ----
324→
325→    /**
326→     * Reads and decompresses a single block by index using the compression map.
327→     */
328→    private byte[] readAndDecompressBlock(int blockIndex) throws IOException {
329→        assert compressionMap != null : "readAndDecompressBlock called on v1 reader";
330→        assert codecMap != null : "codecMap must not be null for v2";
331→
332→        CompressionMap.Entry mapEntry = compressionMap.entry(blockIndex);
333→
334→        if (blockCache != null) {
335→            Optional<MemorySegment> hit = blockCache.get(metadata.id(), blockIndex);
336→            if (hit.isPresent()) {
337→                return hit.get().toArray(ValueLayout.JAVA_BYTE);
338→            }
339→        }
340→
341→        byte[] compressed;
342→        if (eagerData != null) {
343→            compressed = new byte[mapEntry.compressedSize()];
344→            System.arraycopy(eagerData, (int) mapEntry.blockOffset(), compressed, 0,
345→                    mapEntry.compressedSize());
346→        } else {
347→            compressed = readBytes(lazyChannel, mapEntry.blockOffset(), mapEntry.compressedSize());
348→        }
349→
350→        CompressionCodec codec = codecMap.get(mapEntry.codecId());
351→        assert codec != null : "codec not found for ID 0x%02x".formatted(mapEntry.codecId());
352→        byte[] decompressed = codec.decompress(compressed, 0, compressed.length,
353→                mapEntry.uncompressedSize());
354→
355→        if (blockCache != null) {
356→            blockCache.put(metadata.id(), blockIndex, MemorySegment.ofArray(decompressed));
357→        }
358→
359→        return decompressed;
360→    }
361→
362→    /**
363→     * Decompresses all blocks and concatenates them into a single byte array for full scan.
364→     */
365→    private byte[] decompressAllBlocks() throws IOException {
366→        assert compressionMap != null : "decompressAllBlocks called on v1 reader";
367→        int totalUncompressed = 0;
368→        for (int i = 0; i < compressionMap.blockCount(); i++) {
369→            totalUncompressed += compressionMap.entry(i).uncompressedSize();
370→        }
371→        byte[] result = new byte[totalUncompressed];
372→        int off = 0;
373→        for (int i = 0; i < compressionMap.blockCount(); i++) {
374→            byte[] block = readAndDecompressBlock(i);
375→            System.arraycopy(block, 0, result, off, block.length);
376→            off += block.length;
377→        }
378→        assert off == totalUncompressed : "decompressed size mismatch";
379→        return result;
380→    }
381→
382→    private static Map<Byte, CompressionCodec> buildCodecMap(CompressionCodec... codecs) {
383→        Map<Byte, CompressionCodec> map = new HashMap<>();
384→        for (CompressionCodec codec : codecs) {
385→            map.put(codec.codecId(), codec);
386→        }
387→        return Collections.unmodifiableMap(map);
388→    }
389→
390→    private static void validateCodecMap(CompressionMap compressionMap,
391→            Map<Byte, CompressionCodec> codecMap) throws IOException {
392→        for (int i = 0; i < compressionMap.blockCount(); i++) {
393→            byte codecId = compressionMap.entry(i).codecId();
394→            if (!codecMap.containsKey(codecId)) {
395→                throw new IOException(
396→                        "unknown compression codec ID 0x%02x in block %d; available codecs: %s"
397→                                .formatted(codecId, i, codecMap.keySet()));
398→            }
399→        }
400→    }
401→
402→    // ---- v1 internal helpers ----
403→
404→    private void checkNotClosed() throws IOException {
405→        if (closed)
406→            throw new IllegalStateException("reader is closed");
407→    }
408→
409→    /** Returns the data at {@code fileOffset} (v1 absolute offset), reading at most maxBytes. */
410→    private byte[] readDataAtV1(long fileOffset, int maxBytes) throws IOException {
411→        int len = (int) Math.min(maxBytes, dataEnd - fileOffset);
412→        if (len <= 0)
413→            throw new IOException("file offset out of data range: " + fileOffset);
414→
415→        if (blockCache != null) {
416→            Optional<MemorySegment> hit = blockCache.get(metadata.id(), fileOffset);
417→            if (hit.isPresent()) {
418→                return hit.get().toArray(ValueLayout.JAVA_BYTE);
419→            }
420→        }
421→
422→        byte[] data;
423→        if (eagerData != null) {
424→            data = new byte[len];
425→            System.arraycopy(eagerData, (int) fileOffset, data, 0, len);
426→        } else {
427→            data = readBytes(lazyChannel, fileOffset, len);
428→        }
429→
430→        if (blockCache != null) {
431→            blockCache.put(metadata.id(), fileOffset, MemorySegment.ofArray(data));
432→        }
433→        return data;
434→    }
435→
436→    /** Returns the full data region for v1 full scan. */
437→    private byte[] getAllDataV1() throws IOException {
438→        if (eagerData != null)
439→            return eagerData;
440→        return readBytes(lazyChannel, 0L, (int) dataEnd);
441→    }
442→
443→    // ---- Footer / index / filter loading ----
444→
445→    private record Footer(int version, long mapOffset, long mapLength, long idxOffset,
446→            long idxLength, long fltOffset, long fltLength, long entryCount) {
447→    }
448→
449→    /** Reads a v1-only footer. Throws on v2 magic. */
450→    private static Footer readFooterV1(SeekableByteChannel ch, long fileSize) throws IOException {
451→        if (fileSize < SSTableFormat.FOOTER_SIZE) {
452→            throw new IOException("not a valid SSTable file: too small");
453→        }
454→        byte[] buf = readBytes(ch, fileSize - SSTableFormat.FOOTER_SIZE, SSTableFormat.FOOTER_SIZE);
455→        long idxOffset = readLong(buf, 0);
456→        long idxLength = readLong(buf, 8);
457→        long fltOffset = readLong(buf, 16);
458→        long fltLength = readLong(buf, 24);
459→        long entryCount = readLong(buf, 32);
460→        long magic = readLong(buf, 40);
461→        if (magic != SSTableFormat.MAGIC) {
462→            throw new IOException("not a valid SSTable file: bad magic " + Long.toHexString(magic));
463→        }
464→        return new Footer(1, 0, 0, idxOffset, idxLength, fltOffset, fltLength, entryCount);
465→    }
466→
467→    /** Reads footer detecting v1 or v2 format from magic bytes. */
468→    private static Footer readFooter(SeekableByteChannel ch, long fileSize) throws IOException {
469→        if (fileSize < SSTableFormat.FOOTER_SIZE) {
470→            throw new IOException("not a valid SSTable file: too small");
471→        }
472→        // Read the last 8 bytes to check magic
473→        byte[] magicBuf = readBytes(ch, fileSize - 8, 8);
474→        long magic = readLong(magicBuf, 0);
475→
476→        if (magic == SSTableFormat.MAGIC_V2) {
477→            if (fileSize < SSTableFormat.FOOTER_SIZE_V2) {
478→                throw new IOException("not a valid v2 SSTable file: too small");
479→            }
480→            byte[] buf = readBytes(ch, fileSize - SSTableFormat.FOOTER_SIZE_V2,
481→                    SSTableFormat.FOOTER_SIZE_V2);
482→            long mapOffset = readLong(buf, 0);
483→            long mapLength = readLong(buf, 8);
484→            long idxOffset = readLong(buf, 16);
485→            long idxLength = readLong(buf, 24);
486→            long fltOffset = readLong(buf, 32);
487→            long fltLength = readLong(buf, 40);
488→            long entryCount = readLong(buf, 48);
489→            return new Footer(2, mapOffset, mapLength, idxOffset, idxLength, fltOffset, fltLength,
490→                    entryCount);
491→        } else if (magic == SSTableFormat.MAGIC) {
492→            byte[] buf = readBytes(ch, fileSize - SSTableFormat.FOOTER_SIZE,
493→                    SSTableFormat.FOOTER_SIZE);
494→            long idxOffset = readLong(buf, 0);
495→            long idxLength = readLong(buf, 8);
496→            long fltOffset = readLong(buf, 16);
497→            long fltLength = readLong(buf, 24);
498→            long entryCount = readLong(buf, 32);
499→            return new Footer(1, 0, 0, idxOffset, idxLength, fltOffset, fltLength, entryCount);
500→        } else {
501→            throw new IOException("not a valid SSTable file: bad magic " + Long.toHexString(magic));
502→        }
503→    }
504→
505→    /** Reads v1 key index: [numKeys(4)][per key: keyLen(4) + key + fileOffset(8)]. */
506→    private static KeyIndex readKeyIndexV1(SeekableByteChannel ch, Footer footer)
507→            throws IOException {
508→        byte[] buf = readBytes(ch, footer.idxOffset, (int) footer.idxLength);
509→        int numKeys = readInt(buf, 0);
510→        List<MemorySegment> keys = new ArrayList<>(numKeys);
511→        List<Long> offsets = new ArrayList<>(numKeys);
512→        int off = 4;
513→        for (int i = 0; i < numKeys; i++) {
514→            int keyLen = readInt(buf, off);
515→            off += 4;
516→            byte[] keyBytes = new byte[keyLen];
517→            System.arraycopy(buf, off, keyBytes, 0, keyLen);
518→            off += keyLen;
519→            long fileOffset = readLong(buf, off);
520→            off += 8;
521→            keys.add(MemorySegment.ofArray(keyBytes));
522→            offsets.add(fileOffset);
523→        }
524→        return new KeyIndex(keys, offsets);
525→    }
526→
527→    /** Reads v2 key index: [numKeys(4)][per key: keyLen(4) + key + blockIndex(4) + intraOff(4)]. */
528→    private static KeyIndex readKeyIndexV2(SeekableByteChannel ch, Footer footer)
529→            throws IOException {
530→        byte[] buf = readBytes(ch, footer.idxOffset, (int) footer.idxLength);
531→        int numKeys = readInt(buf, 0);
532→        List<MemorySegment> keys = new ArrayList<>(numKeys);
533→        List<Long> offsets = new ArrayList<>(numKeys);
534→        int off = 4;
535→        for (int i = 0; i < numKeys; i++) {
536→            int keyLen = readInt(buf, off);
537→            off += 4;
538→            byte[] keyBytes = new byte[keyLen];
539→            System.arraycopy(buf, off, keyBytes, 0, keyLen);
540→            off += keyLen;
541→            int blockIndex = readInt(buf, off);
542→            off += 4;
543→            int intraBlockOffset = readInt(buf, off);
544→            off += 4;
545→            // Pack into a single long, same encoding as the writer
546→            long packed = ((long) blockIndex << 32) | (intraBlockOffset & 0xFFFFFFFFL);
547→            keys.add(MemorySegment.ofArray(keyBytes));
548→            offsets.add(packed);
549→        }
550→        return new KeyIndex(keys, offsets);
551→    }
552→
553→    private static BloomFilter readBloomFilter(SeekableByteChannel ch, Footer footer,
554→            BloomFilter.Deserializer deserializer) throws IOException {
555→        byte[] buf = readBytes(ch, footer.fltOffset, (int) footer.fltLength);
556→        // Use an Arena-allocated segment to satisfy the alignment constraints of the deserializer
557→        // (BlockedBloomFilter uses JAVA_INT/JAVA_LONG without withByteAlignment(1)).
558→        try (Arena arena = Arena.ofShared()) {
559→            MemorySegment seg = arena.allocate(buf.length, 8);
560→            MemorySegment.copy(MemorySegment.ofArray(buf), 0, seg, 0, buf.length);
561→            return deserializer.deserialize(seg);
562→        }
563→    }
564→
565→    private static SSTableMetadata buildMetadata(Path path, long fileSize, Footer footer,
566→            KeyIndex keyIndex) {
567→        MemorySegment smallestKey = null;
568→        MemorySegment largestKey = null;
569→        Iterator<KeyIndex.Entry> it = keyIndex.iterator();
570→        while (it.hasNext()) {
571→            KeyIndex.Entry e = it.next();
572→            if (smallestKey == null)
573→                smallestKey = e.key();
574→            largestKey = e.key();
575→        }
576→        assert smallestKey != null : "key index must not be empty when building metadata";
577→        return new SSTableMetadata(0L, path, Level.L0, smallestKey, largestKey, SequenceNumber.ZERO,
578→                SequenceNumber.ZERO, fileSize, footer.entryCount);
579→    }
580→
581→    // ---- Low-level I/O ----
582→
583→    private static byte[] readBytes(SeekableByteChannel ch, long offset, int length)
584→            throws IOException {
585→        if (length == 0)
586→            return new byte[0];
587→        ByteBuffer buf = ByteBuffer.allocate(length);
588→        ch.position(offset);
589→        while (buf.hasRemaining()) {
590→            int read = ch.read(buf);
591→            if (read < 0)
592→                throw new IOException("unexpected EOF at offset " + (offset + buf.position()));
593→        }
594→        return buf.array();
595→    }
596→
597→    private static int readInt(byte[] buf, int off) {
598→        return ((buf[off] & 0xFF) << 24) | ((buf[off + 1] & 0xFF) << 16)
599→                | ((buf[off + 2] & 0xFF) << 8) | (buf[off + 3] & 0xFF);
600→    }
601→
602→    private static long readLong(byte[] buf, int off) {
603→        return ((long) (buf[off] & 0xFF) << 56) | ((long) (buf[off + 1] & 0xFF) << 48)
604→                | ((long) (buf[off + 2] & 0xFF) << 40) | ((long) (buf[off + 3] & 0xFF) << 32)
605→                | ((long) (buf[off + 4] & 0xFF) << 24) | ((long) (buf[off + 5] & 0xFF) << 16)
606→                | ((long) (buf[off + 6] & 0xFF) << 8) | (long) (buf[off + 7] & 0xFF);
607→    }
608→
609→    // ---- Iterators ----
610→
611→    /**
612→     * Iterates entries by parsing the raw data region linearly (block by block). Parses: [int
613→     * count][entry...][int count][entry...]... until offset reaches dataEnd.
614→     */
615→    private static final class DataRegionIterator implements Iterator<Entry> {
616→        private final byte[] data;
617→        private final long dataEnd;
618→        private int offset = 0;
619→        private List<Entry> blockEntries = new ArrayList<>();
620→        private int entryIdx = 0;
621→        private Entry next;
622→
623→        DataRegionIterator(byte[] data, long dataEnd) {
624→            this.data = data;
625→            this.dataEnd = dataEnd;
626→            advance();
627→        }
628→
629→        private void advance() {
630→            next = null;
631→            while (true) {
632→                if (entryIdx < blockEntries.size()) {
633→                    next = blockEntries.get(entryIdx++);
634→                    return;
635→                }
636→                if (offset >= dataEnd)
637→                    return;
638→                // Parse next block
639→                int count = readInt(data, offset);
640→                offset += 4;
641→                blockEntries = new ArrayList<>(count);
642→                for (int i = 0; i < count; i++) {
643→                    Entry e = EntryCodec.decode(data, offset);
644→                    blockEntries.add(e);
645→                    offset += EntryCodec.encodedSize(e);
646→                }
647→                entryIdx = 0;
648→            }
649→        }
650→
651→        @Override
652→        public boolean hasNext() {
653→            return next != null;
654→        }
655→
656→        @Override
657→        public Entry next() {
658→            if (next == null)
659→                throw new NoSuchElementException();
660→            Entry result = next;
661→            advance();
662→            return result;
663→        }
664→
665→        private static int readInt(byte[] buf, int off) {
666→            return ((buf[off] & 0xFF) << 24) | ((buf[off + 1] & 0xFF) << 16)
667→                    | ((buf[off + 2] & 0xFF) << 8) | (buf[off + 3] & 0xFF);
668→        }
669→    }
670→
671→    /**
672→     * Iterates entries via key index range results, reading each entry at its offset. Handles both
673→     * v1 (absolute file offset) and v2 (packed blockIndex + intraBlockOffset) formats.
674→     */
675→    private final class IndexRangeIterator implements Iterator<Entry> {
676→        private final Iterator<KeyIndex.Entry> indexIter;
677→        private Entry next;
678→
679→        IndexRangeIterator(Iterator<KeyIndex.Entry> indexIter) {
680→            this.indexIter = indexIter;
681→            advance();
682→        }
683→
684→        private void advance() {
685→            next = null;
686→            if (!indexIter.hasNext())
