package jlsm.sstable.internal;

import jlsm.core.model.Entry;

import java.util.ArrayList;
import java.util.List;

/**
 * A mutable buffer that accumulates encoded entries for a single data block.
 *
 * <p>
 * Block on-disk format:
 *
 * <pre>
 *   [int  count  ]  4 bytes — number of entries in this block
 *   [entry 0 ... ]  variable
 * </pre>
 */
public final class DataBlock {

    private final List<byte[]> encodedEntries = new ArrayList<>();
    private int byteSize = 4; // initial 4 bytes for the count field

    /** Adds an encoded entry to this block. */
    public void add(byte[] encoded) {
        assert encoded != null : "encoded must not be null";
        encodedEntries.add(encoded);
        byteSize += encoded.length;
    }

    /** Returns the current byte size of this block (including the count header). */
    public int byteSize() {
        return byteSize;
    }

    /** Returns the number of entries in this block. */
    public int count() {
        return encodedEntries.size();
    }

    /**
     * Serializes this block to a byte array.
     *
     * @return big-endian serialized form
     */
    public byte[] serialize() {
        byte[] buf = new byte[byteSize];
        int off = 0;
        int count = encodedEntries.size();
        // write count (big-endian int)
        buf[off++] = (byte) (count >>> 24);
        buf[off++] = (byte) (count >>> 16);
        buf[off++] = (byte) (count >>> 8);
        buf[off++] = (byte) count;
        for (byte[] entry : encodedEntries) {
            System.arraycopy(entry, 0, buf, off, entry.length);
            off += entry.length;
        }
        assert off == byteSize : "serialized size mismatch";
        return buf;
    }

    /**
     * Deserializes a list of entries from a raw block byte array.
     *
     * @param blockBytes the raw block bytes
     * @return list of decoded entries
     */
    public static List<Entry> deserialize(byte[] blockBytes) {
        assert blockBytes != null : "blockBytes must not be null";
        assert blockBytes.length >= 4 : "block too short";
        int count = readInt(blockBytes, 0);
        assert count >= 0 : "negative entry count";
        List<Entry> entries = new ArrayList<>(count);
        int off = 4;
        for (int i = 0; i < count; i++) {
            Entry entry = EntryCodec.decode(blockBytes, off);
            entries.add(entry);
            off += EntryCodec.encodedSize(entry);
        }
        return entries;
    }

    private static int readInt(byte[] buf, int off) {
        return ((buf[off] & 0xFF) << 24) | ((buf[off + 1] & 0xFF) << 16)
                | ((buf[off + 2] & 0xFF) << 8) | (buf[off + 3] & 0xFF);
    }
}

// ── Shared JMH + profiler configuration for all benchmark modules ───────────
//
// Apply from each benchmark build.gradle:
//   apply from: "${rootDir}/benchmarks/jmh-common.gradle"
//
// Gradle properties (all optional):
//   -PrunMode=snapshot|sustained    (default: snapshot)
//   -Pprofile                       enable async-profiler
//   -PprofileEvent=cpu|alloc        (default: cpu)
//   -Pjfr                           enable JFR recording (sustained runs)
//   -Pjmh.includes=<regex>          filter benchmark classes
//   -PgcLog                         enable GC text log (sustained runs)

def runMode    = project.findProperty('runMode') ?: 'snapshot'
def isSnapshot = runMode == 'snapshot'

// ── Output directories ──────────────────────────────────────────────────────
def perfOutputDir = "${rootProject.projectDir}/perf-output/${project.name}"

// ── JMH plugin configuration ────────────────────────────────────────────────
jmh {
    jmhVersion = '1.37'
    resultFormat = 'JSON'
    resultsFile = project.file("${perfOutputDir}/results.json")

    if (project.hasProperty('jmh.includes')) {
        includes = [project.property('jmh.includes')]
    }

    if (isSnapshot) {
        fork = 2
        warmupIterations = 3
        iterations = 5
        timeOnIteration = '2s'
        warmup = '1s'
    } else {
        // Sustained: single fork, many iterations, state accumulates
        fork = 1
        warmupIterations = 5
        iterations = 30
        timeOnIteration = '5s'
        warmup = '5s'
    }

    // ── JVM args: profiler accuracy + internal package access ────────────
    def extraJvmArgs = [
        // Profiler accuracy — attribute samples to actual bytecodes, not just safepoints
        '-XX:+UnlockDiagnosticVMOptions',
        '-XX:+DebugNonSafepoints',

        // Enable assertions in benchmarked code
        '-ea',

        // jlsm-core internal packages
        '--add-exports', 'jlsm.core/jlsm.bloom.hash=ALL-UNNAMED',
        '--add-exports', 'jlsm.core/jlsm.wal.internal=ALL-UNNAMED',
        '--add-exports', 'jlsm.core/jlsm.memtable.internal=ALL-UNNAMED',
        '--add-exports', 'jlsm.core/jlsm.sstable.internal=ALL-UNNAMED',
        '--add-exports', 'jlsm.core/jlsm.compaction.internal=ALL-UNNAMED',
        '--add-exports', 'jlsm.core/jlsm.tree.internal=ALL-UNNAMED',

        // jlsm-table internal package
        '--add-exports', 'jlsm.table/jlsm.table.internal=ALL-UNNAMED',

        // jdk.incubator.vector for vector/table benchmarks
        '--add-modules', 'jdk.incubator.vector',
    ]

    // ── GC text log (sustained runs) ────────────────────────────────────
    if (project.hasProperty('gcLog') && !isSnapshot) {
        def gcLogFile = "${perfOutputDir}/gc.log"
        extraJvmArgs += "-Xlog:gc*:file=${gcLogFile}:time,level,tags"
    }

    // ── JFR recording (sustained runs) ──────────────────────────────────
    if (project.hasProperty('jfr') && !isSnapshot) {
        def jfrFile = "${perfOutputDir}/recording.jfr"
        extraJvmArgs += "-XX:StartFlightRecording=filename=${jfrFile},settings=profile,dumponexit=true"
    }

    jvmArgsAppend = extraJvmArgs
}

// ── async-profiler integration ──────────────────────────────────────────────
// Outputs collapsed stacks (text, parseable) instead of HTML flamegraphs.

def osName      = System.getProperty('os.name').toLowerCase(Locale.ROOT)
def isMac       = osName.contains('mac') || osName.contains('darwin')
def profilerLib = isMac ? 'libasyncProfiler.dylib' : 'libasyncProfiler.so'
def profilerDir = rootProject.layout.buildDirectory.dir('async-profiler').get().asFile

if (project.hasProperty('profile')) {
    def event      = project.findProperty('profileEvent') ?: 'cpu'
    def outputFile = event == 'alloc'
        ? "${perfOutputDir}/alloc.collapsed"
        : "${perfOutputDir}/profiler.collapsed"
    def agentPath  = "${profilerDir.absolutePath}/lib/${profilerLib}"

    jmh.fork = 1   // Single fork for clean profiler output
    jmh.jvmArgsAppend = jmh.jvmArgsAppend.get() + [
        "-agentpath:${agentPath}=start,event=${event},file=${outputFile},collapsed"
    ]

    tasks.named('jmh').configure {
        mustRunAfter ':downloadAsyncProfiler'
        doFirst {
            file(perfOutputDir).mkdirs()
            if (!new File(agentPath).exists()) {
                throw new GradleException(
                    "async-profiler not found at ${agentPath}. " +
                    "Run './gradlew :downloadAsyncProfiler' first, or omit -Pprofile.")
            }
        }
    }
} else {
    // Ensure output directory exists even without profiling
    tasks.named('jmh').configure {
        doFirst {
            file(perfOutputDir).mkdirs()
        }
    }
}

// ── Lifecycle task: download profiler + run JMH ─────────────────────────────
tasks.register('jmhProfile') {
    description = 'Download async-profiler and run JMH. Use -Pprofile [-PprofileEvent=cpu|alloc].'
    group       = 'profiling'
    dependsOn ':downloadAsyncProfiler', 'jmh'

    doLast {
        if (!project.hasProperty('profile')) {
            logger.warn('jmhProfile invoked without -Pprofile; benchmarks ran without the profiling agent.')
        }
    }
}

package jlsm.core.model;

import java.lang.foreign.MemorySegment;
import java.util.Objects;

/**
 * Represents a single mutation in the LSM-Tree — either a value insertion or a tombstone deletion.
 *
 * <p>
 * <b>Pipeline position</b>: Entries flow through every stage of the write path (WAL → MemTable →
 * SSTable) and are produced by the read path during scans and point lookups. The sealed hierarchy
 * makes tombstones explicit; callers use {@code switch} pattern matching rather than null checks.
 *
 * <p>
 * <b>Key contracts</b>:
 * <ul>
 * <li>Keys and values are represented as {@link MemorySegment} — compatible with both heap and
 * off-heap allocations; byte ordering is the responsibility of the caller.</li>
 * <li>The {@link SequenceNumber} establishes total ordering for versions of the same key; higher
 * sequence numbers take precedence during compaction.</li>
 * <li>All implementing records are immutable value types.</li>
 * </ul>
 */
public sealed interface Entry permits Entry.Put, Entry.Delete {

    /**
     * Returns the key associated with this entry.
     *
     * @return non-null key segment
     */
    MemorySegment key();

    /**
     * Returns the sequence number that orders this entry among all mutations to the same key.
     *
     * @return non-null sequence number; higher values represent more recent mutations
     */
    SequenceNumber sequenceNumber();

    /**
     * A value-bearing mutation: associates {@code key} with {@code value} at the given sequence
     * number.
     *
     * @param key the key being written; must not be null
     * @param value the value to associate with the key; must not be null
     * @param sequenceNumber the write-order stamp assigned by the WAL; must not be null
     */
    record Put(MemorySegment key, MemorySegment value,
            SequenceNumber sequenceNumber) implements Entry {
        public Put {
            Objects.requireNonNull(key, "key must not be null");
            Objects.requireNonNull(value, "value must not be null");
            Objects.requireNonNull(sequenceNumber, "sequenceNumber must not be null");
        }
    }

    /**
     * A tombstone mutation: marks {@code key} as deleted at the given sequence number. During
     * compaction, a {@code Delete} entry supersedes all {@link Put} entries for the same key with
     * lower sequence numbers.
     *
     * @param key the key being deleted; must not be null
     * @param sequenceNumber the write-order stamp assigned by the WAL; must not be null
     */
    record Delete(MemorySegment key, SequenceNumber sequenceNumber) implements Entry {
        public Delete {
            Objects.requireNonNull(key, "key must not be null");
            Objects.requireNonNull(sequenceNumber, "sequenceNumber must not be null");
        }
    }
}

