206→    /**
207→     * Opens an SSTable file lazily, with support for both v1 and v2 (compressed) formats.
208→     *
209→     * @param path path to the SSTable file
210→     * @param bloomDeserializer deserializer for the bloom filter
211→     * @param blockCache optional block cache, or null
212→     * @param codecs compression codecs available for decompression
213→     * @return a new reader
214→     * @throws IOException if the file cannot be read or contains an unknown codec ID
215→     */
216→    public static TrieSSTableReader openLazy(Path path, BloomFilter.Deserializer bloomDeserializer,
217→            BlockCache blockCache, CompressionCodec... codecs) throws IOException {
218→        Objects.requireNonNull(path, "path must not be null");
219→        Objects.requireNonNull(bloomDeserializer, "bloomDeserializer must not be null");
220→        Objects.requireNonNull(codecs, "codecs must not be null");
221→
222→        SeekableByteChannel ch = Files.newByteChannel(path, StandardOpenOption.READ);
223→        try {
224→            long fileSize = ch.size();
225→            Footer footer = readFooter(ch, fileSize);
226→
227→            CompressionMap compressionMap = null;
228→            Map<Byte, CompressionCodec> codecMap = null;
229→            long dataEnd;
230→            KeyIndex keyIndex;
231→
232→            if (footer.version == 2) {
233→                byte[] mapBytes = readBytes(ch, footer.mapOffset, (int) footer.mapLength);
234→                compressionMap = CompressionMap.deserialize(mapBytes);
235→                codecMap = buildCodecMap(codecs);
236→                validateCodecMap(compressionMap, codecMap);
237→                keyIndex = readKeyIndexV2(ch, footer);
238→                dataEnd = footer.mapOffset;
239→            } else {
240→                keyIndex = readKeyIndexV1(ch, footer);
241→                dataEnd = footer.idxOffset;
242→            }
243→
244→            BloomFilter bloom = readBloomFilter(ch, footer, bloomDeserializer);
245→            SSTableMetadata meta = buildMetadata(path, fileSize, footer, keyIndex);
246→
247→            return new TrieSSTableReader(meta, keyIndex, bloom, dataEnd, null, ch, blockCache,
248→                    compressionMap, codecMap);
249→        } catch (IOException e) {
250→            ch.close();
251→            throw e;
252→        }
253→    }
