 84→        Path path = writeV2SSTable(dir, "none.sst", entries, CompressionCodec.none());
 85→
 86→        try (TrieSSTableReader r = TrieSSTableReader.open(path, BlockedBloomFilter.deserializer(),
 87→                null, CompressionCodec.none())) {
 88→            assertEquals(5L, r.metadata().entryCount());
 89→
 90→            // Verify point lookup
 91→            Optional<Entry> result = r.get(seg("apple"));
 92→            assertTrue(result.isPresent());
 93→            assertInstanceOf(Entry.Put.class, result.get());
 94→            assertEquals(-1L, seg("red").mismatch(((Entry.Put) result.get()).value()));
