 15→import org.junit.jupiter.api.Test;
 16→import org.junit.jupiter.api.io.TempDir;
 17→
 18→import java.io.IOException;
 19→import java.lang.foreign.MemorySegment;
 20→import java.nio.charset.StandardCharsets;
 21→import java.nio.file.Files;
 22→import java.nio.file.Path;
 23→import java.util.ArrayList;
 24→import java.util.Iterator;
 25→import java.util.List;
 26→import java.util.Optional;
 27→import java.util.concurrent.atomic.AtomicLong;
 28→
 29→import static org.junit.jupiter.api.Assertions.*;
 30→
 31→/**
 32→ * Tests for {@link PartitionedTable} — WU-3 coordinator.
 33→ *
 34→ * <p>
 35→ * Uses real in-process LSM trees via {@link InProcessPartitionClient} to exercise end-to-end
 36→ * routing, range fan-out, and lifecycle management.
 37→ */
 38→class PartitionedTableTest {
 39→
 40→    @TempDir
 41→    Path tempDir;
 42→
 43→    private final AtomicLong idCounter = new AtomicLong(0);
 44→
 45→    // -------------------------------------------------------------------------
 46→    // Test helpers
 47→    // -------------------------------------------------------------------------
 48→
 49→    private static JlsmSchema testSchema() {
 50→        return JlsmSchema.builder("test", 1).field("name", FieldType.Primitive.STRING)
 51→                .field("value", FieldType.Primitive.INT32).build();
 52→    }
 53→
 54→    private static MemorySegment seg(String s) {
 55→        return MemorySegment.ofArray(s.getBytes(StandardCharsets.UTF_8));
 56→    }
 57→
 58→    /** Builds a real JlsmTable.StringKeyed backed by an LSM tree in the given directory. */
 59→    private JlsmTable.StringKeyed buildTable(Path dir, JlsmSchema schema) throws IOException {
 60→        final MemorySerializer<JlsmDocument> codec = DocumentSerializer.forSchema(schema);
 61→        final TypedLsmTree.StringKeyed<JlsmDocument> tree = TypedStandardLsmTree
 62→                .<JlsmDocument>stringKeyedBuilder()
 63→                .wal(LocalWriteAheadLog.builder().directory(dir).build())
 64→                .memTableFactory(ConcurrentSkipListMemTable::new)
 65→                .sstableWriterFactory((SSTableWriterFactory) (id, level,
 66→                        path) -> new TrieSSTableWriter(id, level, path))
 67→                .sstableReaderFactory((SSTableReaderFactory) path -> TrieSSTableReader.open(path,
 68→                        BlockedBloomFilter.deserializer()))
 69→                .idSupplier(idCounter::getAndIncrement)
 70→                .pathFn((id, level) -> dir.resolve("sst-" + id + "-L" + level.index() + ".sst"))
 71→                .memTableFlushThresholdBytes(1024 * 1024).valueSerializer(codec).build();
 72→        return StandardJlsmTable.stringKeyedBuilder().lsmTree(tree).schema(schema).build();
 73→    }
 74→
 75→    /**
 76→     * Builds a two-partition setup: partition 1 = [a, m), partition 2 = [m, z{).
 77→     *
 78→     * <p>
 79→     * Returns a PartitionedTable with both partitions backed by real LSM trees. The caller is
 80→     * responsible for closing the returned table.
 81→     */
 82→    private PartitionedTable buildTwoPartitionTable(Path baseDir, JlsmSchema schema)
 83→            throws IOException {
 84→        final Path dir1 = baseDir.resolve("part1");
 85→        final Path dir2 = baseDir.resolve("part2");
 86→        Files.createDirectories(dir1);
 87→        Files.createDirectories(dir2);
 88→
 89→        final PartitionDescriptor desc1 = new PartitionDescriptor(1L, seg("a"), seg("m"), "local",
 90→                0L);
 91→        final PartitionDescriptor desc2 = new PartitionDescriptor(2L, seg("m"), seg("{"), "local",
 92→                0L);
 93→        // Note: '{' is ASCII 123, just above 'z' (122), so [m, {) covers m..z inclusive
 94→
 95→        final PartitionConfig config = PartitionConfig.of(List.of(desc1, desc2));
 96→        final JlsmTable.StringKeyed table1 = buildTable(dir1, schema);
