/**
 * Scratch benchmark: PartitionedTable mixed workload with hotspot analysis.
 *
 * <p>Measures create, get, getRange, and mixed (80/20 read/write) throughput
 * across 4 partitions. Profiles for unexpected hotspots in routing, document
 * serialization, and LSM tree I/O paths.
 */
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.SECONDS)
@State(Scope.Benchmark)
@Warmup(iterations = 3, time = 1)
@Measurement(iterations = 5, time = 2)
@Fork(2)
public class PartitionedTableScratch {

    @Param({"4"})
    int partitions;

    @Param({"1000"})
    int preloadCount;

    private PartitionedTable table;
    private JlsmSchema schema;
    private Path tempDir;
    private final AtomicLong idCounter = new AtomicLong(1);

    // Pre-built keys and docs for benchmarking
    private String[] keys;
    private JlsmDocument[] docs;
    private int writeIndex;
    private int readIndex;
    private int mixedIndex;

