        for (PartitionDescriptor desc : descriptors) {
            Path partDir = tempDir.resolve("part-" + desc.id());
            Files.createDirectories(partDir);
            tables.put(desc.id(), buildTable(partDir));
        }

        return PartitionedTable.builder()
                .partitionConfig(config)
                .schema(schema)
                .partitionClientFactory(desc -> new InProcessPartitionClient(desc, tables.get(desc.id())))
                .build();
    }

    private JlsmTable.StringKeyed buildTable(Path dir) throws IOException {
        MemorySerializer<JlsmDocument> codec = DocumentSerializer.forSchema(schema);
        TypedLsmTree.StringKeyed<JlsmDocument> tree = TypedStandardLsmTree
                .<JlsmDocument>stringKeyedBuilder()
                .wal(LocalWriteAheadLog.builder().directory(dir).build())
                .memTableFactory(ConcurrentSkipListMemTable::new)
                .sstableWriterFactory((id, level, path) -> new TrieSSTableWriter(id, level, path))
                .sstableReaderFactory(path -> TrieSSTableReader.open(path, BlockedBloomFilter.deserializer()))
                .idSupplier(idCounter::getAndIncrement)
