493→    private static Object decodeField(byte[] buf, Cursor cursor, FieldType type) {
494→        return switch (type) {
495→            case FieldType.Primitive p -> switch (p) {
496→                case STRING -> {
497→                    final int len = readVarInt(buf, cursor);
498→                    final String s = new String(buf, cursor.pos, len, StandardCharsets.UTF_8);
499→                    cursor.pos += len;
500→                    yield s;
501→                }
502→                case INT8 -> buf[cursor.pos++];
503→                case INT16 -> {
504→                    final short v = readShortBE(buf, cursor.pos);
505→                    cursor.pos += 2;
506→                    yield v;
507→                }
508→                case INT32 -> {
509→                    final int v = readIntBE(buf, cursor.pos);
510→                    cursor.pos += 4;
511→                    yield v;
512→                }
513→                case INT64 -> {
514→                    final long v = readLongBE(buf, cursor.pos);
515→                    cursor.pos += 8;
516→                    yield v;
517→                }
518→                case FLOAT16 -> {
519→                    final short v = readShortBE(buf, cursor.pos);
520→                    cursor.pos += 2;
521→                    yield v;
522→                }
523→                case FLOAT32 -> {
524→                    final float v = Float.intBitsToFloat(readIntBE(buf, cursor.pos));
525→                    cursor.pos += 4;
526→                    yield v;
527→                }
528→                case FLOAT64 -> {
529→                    final double v = Double.longBitsToDouble(readLongBE(buf, cursor.pos));
530→                    cursor.pos += 8;
531→                    yield v;
532→                }
533→                case BOOLEAN ->
534→                    throw new AssertionError("BOOLEAN should be handled via bool bitmask");
535→                case TIMESTAMP -> {
536→                    final long v = readLongBE(buf, cursor.pos);
537→                    cursor.pos += 8;
538→                    yield v;
539→                }
540→            };
541→            case FieldType.ArrayType at -> decodeArray(buf, cursor, at);
542→            case FieldType.VectorType vt -> decodeVector(buf, cursor, vt);
543→            case FieldType.ObjectType ot -> decodeObject(buf, cursor, ot);
544→        };
545→    }
546→
547→    private static Object[] decodeArray(byte[] buf, Cursor cursor, FieldType.ArrayType at) {
548→        final int count = readVarInt(buf, cursor);
549→        // SIMD-accelerated decode for contiguous numeric types
550→        final FieldType elemType = at.elementType();
551→        if (elemType == FieldType.Primitive.INT32) {
552→            return decodeInt32Array(buf, cursor, count);
553→        } else if (elemType == FieldType.Primitive.INT64) {
554→            return decodeInt64Array(buf, cursor, count);
555→        } else if (elemType == FieldType.Primitive.FLOAT32) {
556→            return decodeFloat32Array(buf, cursor, count);
557→        } else if (elemType == FieldType.Primitive.FLOAT64) {
558→            return decodeFloat64Array(buf, cursor, count);
559→        }
560→        final Object[] arr = new Object[count];
561→        for (int i = 0; i < count; i++) {
562→            arr[i] = decodeField(buf, cursor, elemType);
563→        }
564→        return arr;
565→    }
566→
567→    private static Object decodeVector(byte[] buf, Cursor cursor, FieldType.VectorType vt) {
568→        final int d = vt.dimensions();
569→        if (vt.elementType() == FieldType.Primitive.FLOAT32) {
570→            final float[] vec = new float[d];
571→            for (int i = 0; i < d; i++) {
572→                vec[i] = Float.intBitsToFloat(readIntBE(buf, cursor.pos));
573→                cursor.pos += 4;
574→            }
575→            return vec;
576→        } else {
577→            // FLOAT16 — return as short[]
578→            final short[] vec = new short[d];
579→            for (int i = 0; i < d; i++) {
580→                vec[i] = readShortBE(buf, cursor.pos);
581→                cursor.pos += 2;
582→            }
583→            return vec;
584→        }
585→    }
586→
587→    private static Object decodeObject(byte[] buf, Cursor cursor, FieldType.ObjectType ot) {
588→        final List<FieldDefinition> subFields = ot.fields();
589→        final int subFieldCount = subFields.size();
590→        final int subBoolCount = countBoolFields(subFields);
591→        final int nullMaskBytes = (subFieldCount + 7) / 8;
592→        final int boolMaskBytes = subBoolCount > 0 ? (subBoolCount + 7) / 8 : 0;
593→
594→        final int nullMaskOffset = cursor.advance(nullMaskBytes);
595→        final int boolMaskOffset = subBoolCount > 0 ? cursor.advance(boolMaskBytes) : -1;
596→
597→        final Object[] subValues = new Object[subFieldCount];
598→        int boolIdx = 0;
599→        for (int i = 0; i < subFieldCount; i++) {
600→            final FieldDefinition fd = subFields.get(i);
601→            final boolean isNull = isNullBit(buf, nullMaskOffset, i);
602→            if (isNull) {
603→                if (fd.type() == FieldType.Primitive.BOOLEAN) {
604→                    boolIdx++;
605→                }
606→                subValues[i] = null;
607→                continue;
608→            }
609→            if (fd.type() == FieldType.Primitive.BOOLEAN) {
610→                assert boolMaskOffset >= 0 : "bool bitmask offset should be set";
611→                subValues[i] = isBoolBit(buf, boolMaskOffset, boolIdx);
612→                boolIdx++;
613→            } else {
614→                subValues[i] = decodeField(buf, cursor, fd.type());
615→            }
616→        }
617→
618→        // Synthesize a schema for the sub-document
619→        final JlsmSchema subSchema = ot.toSchema("nested", 0);
620→        return new JlsmDocument(subSchema, subValues);
621→    }
622→
623→    // =========================================================================
624→    // SIMD decode paths
625→    // =========================================================================
626→
627→    private static Object[] decodeInt32Array(byte[] buf, Cursor cursor, int count) {
628→        final Object[] result = new Object[count];
629→        final int simdLen = BYTE_SPECIES.length();
630→        final int simdElems = simdLen / 4;
631→        final int[] tmp = new int[simdElems];
632→        int i = 0;
633→        if (count >= simdElems && simdLen >= 4) {
634→            while (i + simdElems <= count) {
635→                ByteVector.fromArray(BYTE_SPECIES, buf, cursor.pos).rearrange(BSWAP32)
636→                        .reinterpretAsInts().intoArray(tmp, 0);
637→                for (int j = 0; j < simdElems; j++) {
638→                    result[i + j] = tmp[j];
639→                }
640→                cursor.pos += simdLen;
641→                i += simdElems;
642→            }
643→        }
644→        while (i < count) {
645→            result[i++] = readIntBE(buf, cursor.pos);
646→            cursor.pos += 4;
647→        }
648→        return result;
649→    }
650→
651→    private static Object[] decodeInt64Array(byte[] buf, Cursor cursor, int count) {
652→        final Object[] result = new Object[count];
653→        final int simdLen = BYTE_SPECIES.length();
654→        final int simdElems = simdLen / 8;
655→        final long[] tmp = new long[simdElems];
656→        int i = 0;
657→        if (count >= simdElems && simdLen >= 8) {
658→            while (i + simdElems <= count) {
659→                ByteVector.fromArray(BYTE_SPECIES, buf, cursor.pos).rearrange(BSWAP64)
660→                        .reinterpretAsLongs().intoArray(tmp, 0);
661→                for (int j = 0; j < simdElems; j++) {
662→                    result[i + j] = tmp[j];
663→                }
664→                cursor.pos += simdLen;
665→                i += simdElems;
666→            }
667→        }
668→        while (i < count) {
669→            result[i++] = readLongBE(buf, cursor.pos);
670→            cursor.pos += 8;
671→        }
672→        return result;
673→    }
674→
675→    private static Object[] decodeFloat32Array(byte[] buf, Cursor cursor, int count) {
676→        final Object[] result = new Object[count];
677→        final int simdLen = BYTE_SPECIES.length();
678→        final int simdElems = simdLen / 4;
679→        final float[] tmp = new float[simdElems];
680→        int i = 0;
681→        if (count >= simdElems && simdLen >= 4) {
682→            while (i + simdElems <= count) {
683→                ByteVector.fromArray(BYTE_SPECIES, buf, cursor.pos).rearrange(BSWAP32)
684→                        .reinterpretAsFloats().intoArray(tmp, 0);
685→                for (int j = 0; j < simdElems; j++) {
686→                    result[i + j] = tmp[j];
687→                }
688→                cursor.pos += simdLen;
689→                i += simdElems;
690→            }
691→        }
692→        while (i < count) {
693→            result[i++] = Float.intBitsToFloat(readIntBE(buf, cursor.pos));
694→            cursor.pos += 4;
695→        }
696→        return result;
697→    }
698→
699→    private static Object[] decodeFloat64Array(byte[] buf, Cursor cursor, int count) {
700→        final Object[] result = new Object[count];
701→        final int simdLen = BYTE_SPECIES.length();
702→        final int simdElems = simdLen / 8;
703→        final double[] tmp = new double[simdElems];
704→        int i = 0;
705→        if (count >= simdElems && simdLen >= 8) {
706→            while (i + simdElems <= count) {
707→                ByteVector.fromArray(BYTE_SPECIES, buf, cursor.pos).rearrange(BSWAP64)
708→                        .reinterpretAsDoubles().intoArray(tmp, 0);
709→                for (int j = 0; j < simdElems; j++) {
710→                    result[i + j] = tmp[j];
711→                }
712→                cursor.pos += simdLen;
713→                i += simdElems;
714→            }
715→        }
716→        while (i < count) {
717→            result[i++] = Double.longBitsToDouble(readLongBE(buf, cursor.pos));
718→            cursor.pos += 8;
719→        }
720→        return result;
721→    }
722→
723→    // =========================================================================
724→    // Bitmask helpers
725→    // =========================================================================
726→
727→    private static void buildNullMask(List<FieldDefinition> fields, Object[] values, byte[] buf,
728→            int offset) {
729→        for (int i = 0; i < fields.size(); i++) {
730→            if (values[i] == null) {
731→                buf[offset + i / 8] |= (byte) (1 << (i % 8));
732→            }
733→        }
734→    }
735→
736→    private static void buildBoolMask(List<FieldDefinition> fields, Object[] values, byte[] buf,
737→            int offset) {
738→        int boolIdx = 0;
739→        for (int i = 0; i < fields.size(); i++) {
740→            if (fields.get(i).type() == FieldType.Primitive.BOOLEAN) {
741→                final Object val = values[i];
742→                if (val instanceof Boolean b && b) {
743→                    buf[offset + boolIdx / 8] |= (byte) (1 << (boolIdx % 8));
744→                }
745→                boolIdx++;
746→            }
747→        }
748→    }
749→
750→    private static boolean isNullBit(byte[] buf, int maskOffset, int fieldIndex) {
751→        return (buf[maskOffset + fieldIndex / 8] & (1 << (fieldIndex % 8))) != 0;
752→    }
753→
754→    private static boolean isBoolBit(byte[] buf, int maskOffset, int boolIndex) {
755→        return (buf[maskOffset + boolIndex / 8] & (1 << (boolIndex % 8))) != 0;
756→    }
757→
758→    private static int countBoolFields(List<FieldDefinition> fields) {
759→        int count = 0;
760→        for (final FieldDefinition fd : fields) {
761→            if (fd.type() == FieldType.Primitive.BOOLEAN) {
762→                count++;
763→            }
764→        }
765→        return count;
766→    }
767→
768→    private static int countBoolFieldsUpTo(List<FieldDefinition> fields, int limit) {
769→        int count = 0;
770→        final int bound = Math.min(limit, fields.size());
771→        for (int i = 0; i < bound; i++) {
772→            if (fields.get(i).type() == FieldType.Primitive.BOOLEAN) {
773→                count++;
774→            }
775→        }
776→        return count;
777→    }
778→
779→    // =========================================================================
780→    // VarInt (LEB128 unsigned)
781→    // =========================================================================
782→
783→    private static int varIntSize(int value) {
784→        assert value >= 0 : "VarInt value must be non-negative";
785→        if (value < 128) {
786→            return 1;
787→        }
788→        if (value < 16384) {
789→            return 2;
790→        }
791→        if (value < 2097152) {
792→            return 3;
793→        }
794→        if (value < 268435456) {
795→            return 4;
796→        }
797→        return 5;
798→    }
799→
800→    private static void writeVarInt(Cursor c, int value) {
801→        assert value >= 0 : "VarInt value must be non-negative";
802→        while (true) {
803→            if ((value & ~0x7F) == 0) {
804→                c.buf[c.pos++] = (byte) value;
805→                return;
806→            }
807→            c.buf[c.pos++] = (byte) ((value & 0x7F) | 0x80);
808→            value >>>= 7;
809→        }
810→    }
811→
812→    private static int readVarInt(byte[] buf, Cursor cursor) {
813→        int result = 0;
814→        int shift = 0;
815→        while (true) {
816→            final byte b = buf[cursor.pos++];
817→            result |= (b & 0x7F) << shift;
818→            if ((b & 0x80) == 0) {
819→                break;
820→            }
821→            shift += 7;
822→            assert shift <= 35 : "VarInt overflow — corrupt data";
823→        }
824→        return result;
825→    }
826→
827→    // =========================================================================
828→    // Primitive I/O
829→    // =========================================================================
830→
831→    private static void writeShortBE(byte[] buf, int offset, short value) {
832→        buf[offset] = (byte) (value >> 8);
833→        buf[offset + 1] = (byte) value;
834→    }
835→
836→    private static short readShortBE(byte[] buf, int offset) {
837→        return (short) ((buf[offset] << 8) | (buf[offset + 1] & 0xFF));
838→    }
839→
840→    private static void writeIntBE(byte[] buf, int offset, int value) {
841→        buf[offset] = (byte) (value >> 24);
842→        buf[offset + 1] = (byte) (value >> 16);
843→        buf[offset + 2] = (byte) (value >> 8);
844→        buf[offset + 3] = (byte) value;
845→    }
846→
847→    private static int readIntBE(byte[] buf, int offset) {
848→        return ((buf[offset] & 0xFF) << 24) | ((buf[offset + 1] & 0xFF) << 16)
849→                | ((buf[offset + 2] & 0xFF) << 8) | (buf[offset + 3] & 0xFF);
850→    }
851→
852→    private static void writeLongBE(byte[] buf, int offset, long value) {
853→        buf[offset] = (byte) (value >> 56);
854→        buf[offset + 1] = (byte) (value >> 48);
855→        buf[offset + 2] = (byte) (value >> 40);
856→        buf[offset + 3] = (byte) (value >> 32);
857→        buf[offset + 4] = (byte) (value >> 24);
858→        buf[offset + 5] = (byte) (value >> 16);
859→        buf[offset + 6] = (byte) (value >> 8);
860→        buf[offset + 7] = (byte) value;
861→    }
862→
863→    private static long readLongBE(byte[] buf, int offset) {
864→        return ((long) (buf[offset] & 0xFF) << 56) | ((long) (buf[offset + 1] & 0xFF) << 48)
865→                | ((long) (buf[offset + 2] & 0xFF) << 40) | ((long) (buf[offset + 3] & 0xFF) << 32)
866→                | ((long) (buf[offset + 4] & 0xFF) << 24) | ((long) (buf[offset + 5] & 0xFF) << 16)
867→                | ((long) (buf[offset + 6] & 0xFF) << 8) | ((long) (buf[offset + 7] & 0xFF));
868→    }
869→
870→    // =========================================================================
871→    // Cursor
872→    // =========================================================================
873→
874→    /** Mutable position cursor for sequential byte-array I/O. */
875→    private static final class Cursor {
876→
877→        final byte[] buf;
878→        int pos;
879→
880→        Cursor(byte[] buf, int pos) {
881→            this.buf = buf;
882→            this.pos = pos;
883→        }
884→
885→        /** Advances position by {@code n} bytes and returns the old position. */
886→        int advance(int n) {
887→            final int old = pos;
888→            pos += n;
889→            return old;
890→        }
891→    }
892→}
