        JlsmDocument doc = JlsmDocument.of(schema, "vals", vals);
        JlsmDocument out = roundTrip(schema, doc);
        Object[] result = out.getArray("vals");
        assertEquals(vals.length, result.length);
        for (int i = 0; i < vals.length; i++) {
